icitacoes_auth_user_id_chave_idempotencia_key ON engmarq_private.onboarding_solicitacoes USING btree (auth_user_id, chave_idempotencia)"},"optional":false},{"identity":"index:engmarq_private.onboarding_um_resultado_por_usuario","detail":{"definition":"CREATE UNIQUE INDEX onboarding_um_resultado_por_usuario ON engmarq_private.onboarding_solicitacoes USING btree (auth_user_id) WHERE (estado = ''completed''::text)"},"optional":false},{"identity":"view:public.vw_dashboard_documentos","detail":{"definition":" SELECT d.empresa_id,\n    dt.nome AS tipo_nome,\n    d.titulo,\n    d.vencimento,\n        CASE\n            WHEN (d.vencimento IS NULL) THEN ''vigente''::text\n            WHEN (d.vencimento <\n            CASE\n                WHEN (lower(btrim(dt.nome)) = ''aso''::text) THEN ((CURRENT_TIMESTAMP AT TIME ZONE ''America/Sao_Paulo''::text))::date\n                ELSE CURRENT_DATE\n            END) THEN ''vencido''::text\n            WHEN (d.vencimento <= (\n            CASE\n                WHEN (lower(btrim(dt.nome)) = ''aso''::text) THEN ((CURRENT_TIMESTAMP AT TIME ZONE ''America/Sao_Paulo''::text))::date\n                ELSE CURRENT_DATE\n            END +\n            CASE\n                WHEN (lower(btrim(dt.nome)) = ''aso''::text) THEN 30\n                ELSE 60\n            END)) THEN ''vencendo''::text\n            ELSE ''vigente''::text\n        END AS status_calculado,\n    (d.vencimento -\n        CASE\n            WHEN (lower(btrim(dt.nome)) = ''aso''::text) THEN ((CURRENT_TIMESTAMP AT TIME ZONE ''America/Sao_Paulo''::text))::date\n            ELSE CURRENT_DATE\n        END) AS dias_restantes\n   FROM (documentos d\n     JOIN documento_tipos dt ON ((dt.id = d.tipo_id)));"},"optional":false},{"identity":"view:public.vw_dashboard_treinamentos","detail":{"definition":" SELECT t.empresa_id,\n    t.colaborador_id,\n    c.nome AS colaborador_nome,\n    tt.nome AS treinamento_nome,\n    t.data_realizacao,\n    t.data_vencimento,\n        CASE\n            WHEN (t.data_vencimento IS NULL) THEN ''em_dia''::text\n            WHEN (t.data_vencimento < CURRENT_DATE) THEN ''vencido''::text\n            WHEN (t.data_vencimento <= (CURRENT_DATE + ''30 days''::interval)) THEN ''vencendo''::text\n            ELSE ''em_dia''::text\n        END AS status_calculado,\n    (t.data_vencimento - CURRENT_DATE) AS dias_restantes\n   FROM ((treinamentos t\n     JOIN colaboradores c ON ((c.id = t.colaborador_id)))\n     JOIN treinamento_tipos tt ON ((tt.id = t.treinamento_tipo_id)));"},"optional":false},{"identity":"grant:public.ambientes.anon","detail":{"table":[],"columns":[]},"optional":false},{"identity":"grant:public.ambientes.authenticated","detail":{"table":["SELECT"],"columns":["active:INSERT","active:SELECT","active:UPDATE","descricao:INSERT","descricao:SELECT","descricao:UPDATE","empresa_id:INSERT","empresa_id:SELECT","id:SELECT","nome:INSERT","nome:SELECT","nome:UPDATE"]},"optional":false},{"identity":"grant:public.ambientes.service_role","detail":{"table":["DELETE","INSERT","REFERENCES","SELECT","TRIGGER","TRUNCATE","UPDATE"],"columns":["active:INSERT","active:REFERENCES","active:SELECT","active:UPDATE","descricao:INSERT","descricao:REFERENCES","descricao:SELECT","descricao:UPDATE","empresa_id:INSERT","empresa_id:REFERENCES","empresa_id:SELECT","empresa_id:UPDATE","id:INSERT","id:REFERENCES","id:SELECT","id:UPDATE","nome:INSERT","nome:REFERENCES","nome:SELECT","nome:UPDATE"]},"optional":false},{"identity":"grant:public.ambientes_empresa_id_id_key.anon","detail":{"table":[],"columns":[]},"optional":false},{"identity":"grant:public.ambientes_empresa_id_id_key.authenticated","detail":{"table":[],"columns":[]},"optional":false},{"identity":"grant:public.ambientes_empresa_id_id_key.service_role","detail":{"table":[],"columns":[]},"optional":false},{"identity":"grant:public.ambientes_empresa_id_nome_key.anon","detail":{"table":[],"columns":[]},"optional":false},{"identity":"grant:public.ambientes_empresa_id_nome_key.authenticated","d